from pathlib import Path
import sys
import types
import unittest


SCRIPTS = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(SCRIPTS))

# psutil is used by the full scaffolder but is not needed for these naming
# tests and is optional in the lightweight development test environment.
sys.modules.setdefault("psutil", types.ModuleType("psutil"))

from scaffolding import scaffold_graph


class FakePaths:
    def __init__(self, entries):
        self.entries = entries

    def getPathIds(self):
        return self.entries.keys()

    def getLabel(self, path_id):
        return self.entries[path_id]


class ScaffoldingPhaseNameTests(unittest.TestCase):
    def test_recognizes_full_and_legacy_trio_names(self):
        cases = (
            ("maternal_from_utig4-1", "MATERNAL"),
            ("paternal_from_utig4-1", "PATERNAL"),
            ("mat_from_utig4-1", "MAT"),
            ("pat_from_utig4-1", "PAT"),
        )
        for path_id, label in cases:
            with self.subTest(path_id=path_id):
                paths = FakePaths({path_id: label})
                self.assertTrue(scaffold_graph.uses_trio_naming(paths))

    def test_does_not_treat_generic_haplotypes_as_trio(self):
        paths = FakePaths({"haplotype1_from_utig4-1": "HAPLOTYPE1"})
        self.assertFalse(scaffold_graph.uses_trio_naming(paths))

    def test_haploid_reassignment_returns_before_hic_heuristics_for_trio(self):
        paths = FakePaths({"paternal_from_utig4-1": "PATERNAL"})
        scaffolder = scaffold_graph.ScaffoldGraph.__new__(scaffold_graph.ScaffoldGraph)
        scaffolder.getHaploidPaths = lambda unused_paths: self.fail(
            "trio paths reached the Hi-C-only haploid reassignment heuristic"
        )

        scaffolder.fixHaploidNames(paths)

    def test_rephase_maps_preserve_each_naming_vocabulary(self):
        expected_labels = {
            "MATERNAL": "PATERNAL",
            "PATERNAL": "MATERNAL",
            "MAT": "PAT",
            "PAT": "MAT",
            "HAPLOTYPE1": "HAPLOTYPE2",
            "HAPLOTYPE2": "HAPLOTYPE1",
        }
        expected_prefixes = {
            "maternal": "paternal",
            "paternal": "maternal",
            "mat": "pat",
            "pat": "mat",
            "haplotype1": "haplotype2",
            "haplotype2": "haplotype1",
        }
        self.assertEqual(scaffold_graph.PHASE_LABEL_SWITCH, expected_labels)
        self.assertEqual(scaffold_graph.PHASE_PREFIX_SWITCH, expected_prefixes)


if __name__ == "__main__":
    unittest.main()
